/**
 * PURPOSE:
 * - Extract raw text output from LLM
 * - Sanitize markdown/code fences
 * - Parse JSON safely
 * - Flatten frames (1–13) into a single n8n-friendly object
 */

// 1. Extract raw text from LLM output
let raw = $input.first().json.content.parts[0].text;

// 2. Remove markdown code fences if present
raw = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// 3. Debug log (viewable in Execution Logs)
console.log("SANITIZED RAW OUTPUT:\n", raw);

// 4. Parse JSON safely
let frames;
try {
  frames = JSON.parse(raw);
} catch (error) {
  throw new Error(
    "JSON parsing failed. LLM output is not valid JSON.\n" +
    "Error: " + error.message + "\n\n" +
    "Raw Output:\n" + raw
  );
}

// 5. Validate structure
if (!Array.isArray(frames)) {
  throw new Error("Parsed JSON is not an array.");
}

// 6. Flatten frames into key-value pairs
let output = {};

frames.forEach(frame => {
  const index = frame.frame;

  output[`frame_${index}_step_name`] = frame.step_name || "";
  output[`frame_${index}_analysis_notes`] = frame.analysis_notes || "";
  output[`frame_${index}_edit_instruction`] = frame.edit_instruction || "";
});

// 7. Return result
return [
  {
    json: output
  }
];
